mapper.select:
SELECT r.check_in_id AS checkInId,
       a.title AS activityTitle,
       r.student_id AS studentId,
       s.student_no AS studentNo,
       s.name AS studentName,
       COALESCE(r.class_code, s.class_code) AS classCode,
       r.check_date AS checkDate,
       r.checked_in AS checkedIn,
       r.check_time AS checkTime
FROM student_check_in_record r
         LEFT JOIN check_in_activity a ON a.check_in_id = r.check_in_id
         LEFT JOIN student_profile s ON s.id = r.student_id
WHERE r.check_date BETWEEN #{beginDate} AND #{endDate}

    AND r.student_id = #{studentId}


    AND r.check_in_id = #{checkInId}


    AND a.teacher_user_id = #{teacherUserId}

ORDER BY r.check_time DESC, r.student_id ASC
LIMIT #{pageSize}
OFFSET #{offset}

SELECT COUNT(*)
FROM student_check_in_record r
         LEFT JOIN check_in_activity a ON a.check_in_id = r.check_in_id
WHERE r.check_date BETWEEN #{beginDate} AND #{endDate}

    AND r.student_id = #{studentId}


    AND r.check_in_id = #{checkInId}


    AND a.teacher_user_id = #{teacherUserId}


    AND r.status = #{status}

SELECT s.checked_in
FROM student_check_in_record AS s
WHERE s.student_id = #{studentId}
  AND s.check_date = #{checkDate}
  AND (#{checkInId} IS NULL OR s.check_in_id = #{checkInId})

SELECT EXISTS (
    SELECT 1
    FROM student_check_in_record
    WHERE check_in_id = #{checkInId}
      AND student_id = #{studentId}
)
